package com.ruoyi.ai.agent;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.*;
import junit.framework.TestCase;
import java.lang.reflect.*;
import java.util.*;
import static com.ruoyi.ai.agent.AgentJson.*;

/** Real isolated MySQL. Reflection preserves a runnable red phase for new contracts. */
public class B2BoundaryTest extends TestCase {
    private A1TestFixture f;private ControlledWriteService service;
    protected void setUp()throws Exception{f=new A1TestFixture();service=new ControlledWriteService(new AgentStore(f.db),f.guard,f.workbooks,f.versions,f.tx.getTransactionManager());A1TestFixture.inject(service,"enabled",true);}
    private Object invoke(Object target,String method,Class<?>[] types,Object... args){try{return (target instanceof Class?(Class<?>)target:target.getClass()).getMethod(method,types).invoke(target instanceof Class?null:target,args);}catch(InvocationTargetException e){if(e.getCause() instanceof RuntimeException)throw(RuntimeException)e.getCause();throw new RuntimeException(e.getCause());}catch(Exception e){throw new AssertionError("Missing B2 contract: "+method,e);}}
    private String classify(String actions){return(String)invoke(WriteManifest.class,"classify",new Class[]{JsonNode.class},parse(actions));}
    private void reject(Runnable action){try{action.run();fail("Unsafe action accepted");}catch(IllegalArgumentException expected){assertNotNull(expected.getMessage());}}
    private ObjectNode request(String entry){long w=f.seed("{\"id\":\"b2\",\"sheetOrder\":[\"s\"],\"sheets\":{\"s\":{\"id\":\"s\",\"name\":\"Orders\",\"rowCount\":20,\"columnCount\":10,\"cellData\":{}}}}");ObjectNode s=f.runs.workspace(w,1);ObjectNode r=obj().put("entryPoint",entry).put("requestId",UUID.randomUUID().toString()).put("workbookId",w).put("branchId",s.path("branchId").asLong()).put("expectedDraftVersion",s.path("draftVersion").asLong()).put("expectedBranchVersion",s.path("branchVersion").asLong()).put("loadedRevision",s.path("loadedRevision").asText()).put("activeSheetId","s").put("overwrite","empty-only");r.set("writeScopes",arr().add(obj().put("sheetId","s").put("range","B2:C3")));r.set("actions",parse("[{\"type\":\"setCell\",\"schemaVersion\":\"1.0\",\"sheetId\":\"s\",\"range\":\"B2\",\"value\":11},{\"type\":\"setValues\",\"schemaVersion\":\"2.0\",\"target\":{\"sheetId\":\"s\",\"range\":\"B3:C3\"},\"values\":[[21,22]]}]"));return r;}
    private ObjectNode claim(ObjectNode run){return service.claim(run.path("runId").asText(),1,obj().put("clientId","b2").put("fencingToken",run.path("fencingToken").asLong()));}
    private ObjectNode identity(ObjectNode m){return obj().put("callId",m.path("callId").asText()).put("claimToken",m.path("claimToken").asText()).put("argsHash",m.path("argsHash").asText()).put("fencingToken",m.path("fencingToken").asLong());}
    private ObjectNode ok(ObjectNode m){ObjectNode r=identity(m).put("transportVersion",2).put("ok",true);ArrayNode cells=arr();for(JsonNode c:m.path("cells")){ObjectNode copy=c.deepCopy();copy.remove("before");copy.put("formula","");cells.add(copy);}r.set("cells",cells);return r;}
    private ObjectNode uncertain(ObjectNode run,ObjectNode req){return(ObjectNode)invoke(service,"uncertain",new Class[]{String.class,long.class,ObjectNode.class},run.path("runId").asText(),1L,req);}
    public void testReadAndChartRemainReadDisplay(){assertEquals("read-display",classify("[{\"type\":\"getRangeValue\"},{\"type\":\"createChart\"}]"));assertEquals("read-display",classify("[]"));}
    public void testOnlyScalarWritesAreControlled(){assertEquals("controlled-values",classify("[{\"type\":\"setCell\"},{\"type\":\"setValues\"}]"));}
    public void testUnmigratedAndMixedGroupsRejected(){for(String type:Arrays.asList("setFormula","setStyle","setFilter","clearFilter","undo","redo","sumToCell","deleteRows","unknown"))reject(()->classify("[{\"type\":\""+type+"\"}]"));reject(()->classify("[{\"type\":\"getSelection\"},{\"type\":\"setCell\"}]"));}
    public void testOldChatClientCannotReceiveExecutableWrites(){reject(()->invoke(WriteManifest.class,"checkChatTransport",new Class[]{JsonNode.class,JsonNode.class,boolean.class},parse("[{\"type\":\"setCell\"}]"),obj(),true));}
    public void testEntrypointsProduceSameTrustedContentAndVersion(){String content=null;for(String entry:Arrays.asList("ordinary-ai","plan-agent")){ObjectNode req=request(entry),run=service.create(req,1);assertEquals(entry,run.path("entryPoint").asText());ObjectNode result=service.receipt(run.path("runId").asText(),1,ok(claim(run)));assertEquals("COMPLETED",result.path("status").asText());Map<String,Object>s=f.status(req.path("workbookId").asLong());assertEquals(0,((Number)((Map<?,?>)s.get("workingState")).get("version")).intValue());if(content==null)content=String.valueOf(s.get("content"));else assertEquals(content,s.get("content"));}}
    public void testLostUnsavedReceiptPausesAndCannotReplay(){ObjectNode req=request("ordinary-ai"),run=service.create(req,1),m=claim(run);ObjectNode paused=uncertain(run,identity(m));assertEquals("PAUSED",paused.path("status").asText());assertEquals("UNKNOWN",paused.path("call").path("status").asText());assertNull(f.status(req.path("workbookId").asLong()).get("workingState"));reject(()->service.claim(run.path("runId").asText(),1,obj().put("clientId","retry").put("fencingToken",run.path("fencingToken").asLong())));reject(()->service.receipt(run.path("runId").asText(),1,ok(m)));}
    public void testLostAcknowledgementFindsSavedLedgerWithoutVersionIncrement(){ObjectNode req=request("ordinary-ai"),run=service.create(req,1),m=claim(run);ObjectNode receipt=ok(m);service.receipt(run.path("runId").asText(),1,receipt);assertEquals("COMPLETED",uncertain(run,identity(m)).path("status").asText());service.receipt(run.path("runId").asText(),1,receipt);assertEquals(0,((Number)((Map<?,?>)f.status(req.path("workbookId").asLong()).get("workingState")).get("version")).intValue());}
    public void testUncertainRequestRequiresOriginalClaimIdentity(){ObjectNode run=service.create(request("ordinary-ai"),1),m=claim(run);ObjectNode wrong=identity(m).put("claimToken","wrong");reject(()->uncertain(run,wrong));assertEquals("EXECUTING",f.runs.get(run.path("runId").asText(),1).path("status").asText());}
    private ObjectNode advance(String id)throws Exception{Method advance=AgentRunService.class.getDeclaredMethod("advance",ObjectNode.class);advance.setAccessible(true);return f.tx.execute(tx->{AgentStore store=new AgentStore(f.db);ObjectNode preview=store.get(id);f.guard.lock(preview.path("workbookId").asLong(),1L);ObjectNode r=store.locked(id);try{advance.invoke(f.runs,r);}catch(Exception e){throw new RuntimeException(e);}store.save(r);return r;});}
    public void testRealAgentSchedulerAndOrdinaryEntrySharePersistenceSemantics()throws Exception{
        ObjectNode ordinary=request("ordinary-ai");((ArrayNode)ordinary.path("actions")).add(obj().put("type","setCell").put("sheetId","s").put("range","C2").put("value",12));ObjectNode direct=service.create(ordinary,1);service.receipt(direct.path("runId").asText(),1,ok(claim(direct)));
        ObjectNode agent=request("plan-agent");agent.set("actions",ordinary.path("actions"));agent.put("goal","write and verify").put("expectedRevision",f.runs.workspace(agent.path("workbookId").asLong(),1).path("revision").asText());
        A1TestFixture.inject(f.guard,"enabled",true);A1TestFixture.inject(f.runs,"controlled",service);A1TestFixture.inject(f.runs,"timeoutMs",900000L);
        ObjectNode run=f.runs.create(agent,1);String id=run.path("runId").asText();
        f.tx.execute(tx->{AgentStore store=new AgentStore(f.db);ObjectNode r=store.locked(id);ObjectNode plan=(ObjectNode)parse("{\"steps\":[{\"stepId\":\"W\",\"objective\":\"write\",\"tool\":\"apply_actions\",\"dependsOn\":[],\"inputBindings\":{\"overwrite\":\"empty-only\"},\"verificationRules\":[{\"type\":\"tool_success\"}]},{\"stepId\":\"V\",\"objective\":\"verify\",\"tool\":\"verify_result\",\"dependsOn\":[\"W\"],\"inputBindings\":{\"write\":{\"$step\":\"W\"},\"sheetId\":\"s\",\"range\":\"B2:C3\",\"kind\":\"non_empty\"},\"verificationRules\":[{\"type\":\"tool_success\"}]}],\"acceptanceCriteria\":[{\"type\":\"step_succeeded\",\"stepId\":\"W\"},{\"type\":\"step_succeeded\",\"stepId\":\"V\"}]}");((ObjectNode)plan.path("steps").get(0).path("inputBindings")).set("actions",agent.path("actions"));r.set("plan",plan);r.put("planVersion",1).put("stepIndex",0).put("status","EXECUTING");store.save(r);return null;});
        ObjectNode executing=advance(id),manifest=claim(executing);f.runs.receiptControlled(id,1,ok(manifest));advance(id);assertEquals("COMPLETED",advance(id).path("status").asText());
        Map<String,Object> a=f.status(ordinary.path("workbookId").asLong()),b=f.status(agent.path("workbookId").asLong());assertEquals(a.get("content"),b.get("content"));assertEquals(a.get("loadedRevision"),b.get("loadedRevision"));assertEquals(((Map<?,?>)a.get("workingState")).get("version"),((Map<?,?>)b.get("workingState")).get("version"));
    }
}
